        ctx.fillStyle = 'blue';
        ctx.fillText('Hello Canvas!', 50, 50);

        ctx.font = '20px Courier New';
        ctx.strokeStyle = 'red';
        ctx.strokeText('Outlined Text', 50, 100);

        // Text with alignment
        ctx.font = 'bold 24px Verdana';
        ctx.textAlign = 'center';
        ctx.fillStyle = 'green';
        ctx.fillText('Centered Text', canvas.width/2, 150);

        // Draw image from URL
        const img = new Image();
        img.src = 'https://via.placeholder.com/150';
        img.onload = function() {
            ctx.drawImage(img, 50, 180, 100, 100);
            ctx.drawImage(img, 200, 180, 150, 150);
        };

        // Draw image from existing img element
        const existingImg = document.createElement('img');
        existingImg.src = 'https://via.placeholder.com/80';
        existingImg.onload = function() {
            ctx.drawImage(existingImg, 400, 180);
        };

        // Text metrics
        const text = 'Measure me';
        const metrics = ctx.measureText(text);
        console.log('Text width:', metrics.width);
