<!DOCTYPE html>
<html>
<body>
    <!-- Data attributes store custom data on HTML elements -->
    <div id="user-card" 
         data-user-id="12345" 
         data-user-role="admin" 
         data-last-login="2024-01-15"
         data-preferences='{"theme":"dark","notifications":true}'>
        John Doe
    </div>

    <button data-action="delete" data-id="42" data-confirm="true">
        Delete Item
    </button>

    <ul>
        <li data-product-id="1001" data-price="29.99">Product 1</li>
        <li data-product-id="1002" data-price="49.99">Product 2</li>
        <li data-product-id="1003" data-price="19.99">Product 3</li>
    </ul>

    <script>
        // Access data attributes with dataset
        const userCard = document.getElementById('user-card');

        // Reading data attributes (camelCase conversion)
        console.log(userCard.dataset.userId);      // "12345"
        console.log(userCard.dataset.userRole);    // "admin"
        console.log(userCard.dataset.lastLogin);   // "2024-01-15"

        // Parse JSON data
        const preferences = JSON.parse(userCard.dataset.preferences);
        console.log(preferences.theme);  // "dark"

        // Writing data attributes
        userCard.dataset.isActive = 'true';
        // Adds: data-is-active="true"

        // Remove data attribute
        delete userCard.dataset.lastLogin;

        // Iterate all data attributes
        for (const [key, value] of Object.entries(userCard.dataset)) {
            console.log(`${key}: ${value}`);
        }

        // Event delegation using data attributes
        document.querySelectorAll('[data-product-id]').forEach(item => {
            item.addEventListener('click', () => {
                const productId = item.dataset.productId;
                const price = item.dataset.price;
                alert(`Product ${productId} costs $${price}`);
            });
        });

        // CSS selection with data attributes
        // [data-user-role="admin"] { background-color: gold; }
        // [data-active="true"] { border: 2px solid green; }
    </script>
</body>
</html>
```

**Data attribute rules:**
- Must be prefixed with `data-`
- Can store any string data
- `dataset` converts kebab-case to camelCase (`data-user-id` → `userId`)
- Useful for storing state, passing data to JS, testing hooks
- Don't store sensitive data (visible in HTML source)

