    <form id="currency">
        <label>USD: $<input type="number" id="usd" value="100" step="10"></label>
        <label>Exchange rate: <input type="number" id="rate" value="0.85" step="0.01"></label>
        <br>
        EUR: <output name="eur">85</output>
    </form>

    <!-- BMI Calculator -->
    <form id="bmiCalc" onsubmit="return false">
        <label>Weight (kg): <input type="number" id="weight" value="70" step="1"></label>
        <label>Height (m): <input type="number" id="height" value="1.75" step="0.01"></label>
        <br>
        BMI: <output id="bmi">22.86</output>
        <br>
        <button type="button" onclick="calculateBMI()">Calculate</button>
    </form>

    <script>
        // Advanced calculator with real-time updates
        const num1 = document.getElementById('num1');
        const num2 = document.getElementById('num2');
        const sumOut = document.querySelector('[name="sum"]');
        const productOut = document.querySelector('[name="product"]');
        const diffOut = document.querySelector('[name="diff"]');
        const avgOut = document.querySelector('[name="avg"]');

        function updateCalculations() {
            const a = parseFloat(num1.value) || 0;
            const b = parseFloat(num2.value) || 0;
            sumOut.value = a + b;
            productOut.value = a * b;
            diffOut.value = a - b;
            avgOut.value = (a + b) / 2;
        }

        num1.addEventListener('input', updateCalculations);
        num2.addEventListener('input', updateCalculations);
        updateCalculations();

        // Currency converter
        const usd = document.getElementById('usd');
        const rate = document.getElementById('rate');
        const eurOut = document.querySelector('[name="eur"]');

        function convertCurrency() {
            const usdVal = parseFloat(usd.value) || 0;
            const rateVal = parseFloat(rate.value) || 0;
            eurOut.value = (usdVal * rateVal).toFixed(2);
        }

        usd.addEventListener('input', convertCurrency);
        rate.addEventListener('input', convertCurrency);
        convertCurrency();

        // BMI Calculator
        function calculateBMI() {
            const weight = parseFloat(document.getElementById('weight').value);
            const height = parseFloat(document.getElementById('height').value);
            if (weight > 0 && height > 0) {
                const bmi = weight / (height * height);
                document.getElementById('bmi').value = bmi.toFixed(2);
            }
