<!DOCTYPE html>
<html>
<head>
    <title>LocalStorage Example</title>
    <style>
        body { font-family: Arial; max-width: 600px; margin: 50px auto; padding: 20px; }
        input, button { margin: 5px; padding: 8px; }
        .saved { background: #e0ffe0; padding: 10px; margin: 10px 0; }
    </style>
</head>
<body>
    <h1>LocalStorage Demo</h1>

    <h2>Save User Preferences</h2>
    <label>Username: <input type="text" id="username" placeholder="Enter name"></label>
    <label>Theme: 
        <select id="theme">
            <option value="light">Light</option>
            <option value="dark">Dark</option>
        </select>
    </label>
    <button onclick="savePreferences()">Save Preferences</button>
    <button onclick="clearPreferences()">Clear All</button>

    <div id="savedData" class="saved"></div>

    <h2>Notes App (auto-save)</h2>
    <textarea id="notes" rows="5" cols="50" placeholder="Write your notes..."></textarea>
    <p>Notes are automatically saved as you type!</p>

    <script>
        // Save data to localStorage
        function savePreferences() {
            const username = document.getElementById('username').value;
            const theme = document.getElementById('theme').value;

            localStorage.setItem('username', username);
            localStorage.setItem('theme', theme);

            // Save object as JSON
            const userPrefs = { username, theme, timestamp: new Date().toISOString() };
            localStorage.setItem('userPrefs', JSON.stringify(userPrefs));

            displaySavedData();
            applyTheme(theme);
        }

        // Load data from localStorage on page load
        function loadPreferences() {
            const savedUsername = localStorage.getItem('username');
            const savedTheme = localStorage.getItem('theme');

            if (savedUsername) {
                document.getElementById('username').value = savedUsername;
            }
            if (savedTheme) {
                document.getElementById('theme').value = savedTheme;
                applyTheme(savedTheme);
            }
            displaySavedData();
        }

        // Display all saved data
        function displaySavedData() {
            const output = document.getElementById('savedData');
            output.innerHTML = '<strong>Saved in localStorage:</strong><br>';
            for (let i = 0; i < localStorage.length; i++) {
                const key = localStorage.key(i);
                const value = localStorage.getItem(key);
                output.innerHTML += `${key}: ${value}<br>`;
            }
        }

        // Clear all localStorage
        function clearPreferences() {
            localStorage.clear();
            displaySavedData();
            document.getElementById('username').value = '';
            document.getElementById('theme').value = 'light';
            applyTheme('light');
        }

        // Apply theme
        function applyTheme(theme) {
            if (theme === 'dark') {
                document.body.style.backgroundColor = '#333';
                document.body.style.color = '#fff';
            } else {
                document.body.style.backgroundColor = '#fff';
                document.body.style.color = '#000';
            }
        }

        // Auto-save notes on input
        const notesTextarea = document.getElementById('notes');
        const savedNotes = localStorage.getItem('notes');
        if (savedNotes) {
            notesTextarea.value = savedNotes;
        }

        notesTextarea.addEventListener('input', () => {
            localStorage.setItem('notes', notesTextarea.value);
        });

        // Load saved data on page load
        loadPreferences();

        // Display localStorage info
        console.log('LocalStorage length:', localStorage.length);
        console.log('Remaining space estimate:', navigator.storage?.estimate());
    </script>

    <hr>
    <h3>LocalStorage API Methods</h3>
    <ul>
        <li><code>localStorage.setItem(key, value)</code> - store data</li>
        <li><code>localStorage.getItem(key)</code> - retrieve data</li>
        <li><code>localStorage.removeItem(key)</code> - remove specific item</li>
        <li><code>localStorage.clear()</code> - remove all items</li>
        <li><code>localStorage.key(index)</code> - get key by index</li>
        <li><code>localStorage.length</code> - number of stored items</li>
    </ul>
    <p><strong>Limitations:</strong> ~5-10MB per domain, stores only strings (use JSON.stringify/parse for objects)</p>
</body>
</html>
```

**LocalStorage vs SessionStorage:**
- `localStorage`: persists until explicitly deleted (across browser sessions)
- `sessionStorage`: persists only for current tab/session (cleared when tab closes)
- Both are synchronous, store key-value pairs as strings
- Data is domain-specific (not shared across different websites)

```html
<!DOCTYPE html>
<html>
<head>
    <title>SessionStorage Demo</title>
    <style>
        body { font-family: Arial; max-width: 700px; margin: 30px auto; padding: 20px; }
        .card { border: 1px solid #ccc; padding: 15px; margin: 10px 0; border-radius: 8px; }
        button { margin: 5px; padding: 8px 12px; cursor: pointer; }
        .warning { background: #fff3cd; border-left: 4px solid #ffc107; padding: 10px; }
    </style>
</head>
<body>
    <h1>SessionStorage Demo</h1>
    <div class="warning">
        ⚠️ SessionStorage data is cleared when you close this tab or browser.
        Refresh the page to see data persists within the same session.
    </div>

    <div class="card">
        <h2>Multi-step Form (Wizard)</h2>
        <div id="step1">
            <h3>Step 1: Personal Info</h3>
            <label>Name: <input type="text" id="name" placeholder="Full name"></label><br>
            <label>Email: <input type="email" id="email" placeholder="Email"></label><br>
            <button onclick="nextStep(2)">Next →</button>
        </div>
        <div id="step2" style="display:none">
            <h3>Step 2: Preferences</h3>
            <label>Favorite Color: <input type="text" id="color" placeholder="Color"></label><br>
            <label>Newsletter: <input type="checkbox" id="newsletter"> Subscribe</label><br>
            <button onclick="prevStep(1)">← Back</button>
            <button onclick="saveForm()">Submit</button>
        </div>
    </div>

    <div class="card">
        <h2>Tab-specific Shopping Cart</h2>
        <div id="cart">
            <button onclick="addToCart('Laptop')">Add Laptop ($999)</button>
            <button onclick="addToCart('Mouse')">Add Mouse ($29)</button>
            <button onclick="addToCart('Keyboard')">Add Keyboard ($79)</button>
            <button onclick="clearCart()">Clear Cart</button>
        </div>
        <h3>Your Cart (session only):</h3>
        <ul id="cartItems"></ul>
        <p><strong>Total:</strong> $<span id="cartTotal">0</span></p>
    </div>

    <div class="card">
        <h2>Session Data Viewer</h2>
        <button onclick="displaySessionData()">Refresh Session Data</button>
        <pre id="sessionData"></pre>
        <button onclick="clearSession()">Clear All Session Data</button>
    </div>

    <script>
        // SessionStorage API (identical to localStorage but session-scoped)

        // Multi-step form wizard
        function nextStep(step) {
            // Save current step data to sessionStorage
            const step1Data = {
                name: document.getElementById('name').value,
                email: document.getElementById('email').value
            };
            sessionStorage.setItem('wizard_step1', JSON.stringify(step1Data));
            sessionStorage.setItem('wizard_currentStep', step);

            // Load step2 data if exists
            const step2Data = JSON.parse(sessionStorage.getItem('wizard_step2') || '{}');
            if (step2Data.color) document.getElementById('color').value = step2Data.color;
            if (step2Data.newsletter) document.getElementById('newsletter').checked = step2Data.newsletter;

            document.getElementById('step1').style.display = 'none';
            document.getElementById('step2').style.display = 'block';
        }

        function prevStep(step) {
            // Save step2 data
            const step2Data = {
                color: document.getElementById('color').value,
                newsletter: document.getElementById('newsletter').checked
            };
            sessionStorage.setItem('wizard_step2', JSON.stringify(step2Data));

            document.getElementById('step2').style.display = 'none';
            document.getElementById('step1').style.display = 'block';
        }

        function saveForm() {
            const step1 = JSON.parse(sessionStorage.getItem('wizard_step1') || '{}');
            const step2 = {
                color: document.getElementById('color').value,
                newsletter: document.getElementById('newsletter').checked
            };
            const completeData = { ...step1, ...step2, submittedAt: new Date().toISOString() };
            sessionStorage.setItem('wizard_complete', JSON.stringify(completeData));
            alert('Form submitted! Data saved to sessionStorage.');
            displaySessionData();
        }

        // Shopping cart
        let cart = JSON.parse(sessionStorage.getItem('cart') || '[]');

        function addToCart(item) {
            const prices = { Laptop: 999, Mouse: 29, Keyboard: 79 };
            cart.push({ item, price: prices[item] });
            sessionStorage.setItem('cart', JSON.stringify(cart));
            updateCartDisplay();
        }

        function clearCart() {
            cart = [];
            sessionStorage.setItem('cart', JSON.stringify(cart));
            updateCartDisplay();
        }

        function updateCartDisplay() {
            const cartList = document.getElementById('cartItems');
            cartList.innerHTML = '';
            let total = 0;
            cart.forEach((item, index) => {
                cartList.innerHTML += `<li>${item.item} - $${item.price} <button onclick="removeFromCart(${index})">Remove</button></li>`;
                total += item.price;
            });
            document.getElementById('cartTotal').innerText = total;
        }

        function removeFromCart(index) {
            cart.splice(index, 1);
            sessionStorage.setItem('cart', JSON.stringify(cart));
            updateCartDisplay();
        }

        // Display all sessionStorage data
        function displaySessionData() {
            const output = document.getElementById('sessionData');
            output.textContent = '';
            for (let i = 0; i < sessionStorage.length; i++) {
                const key = sessionStorage.key(i);
                const value = sessionStorage.getItem(key);
                output.textContent += `${key}: ${value}\n`;
            }
            if (sessionStorage.length === 0) {
                output.textContent = '(No session data)';
            }
        }

        function clearSession() {
            sessionStorage.clear();
            cart = [];
            updateCartDisplay();
            displaySessionData();
            location.reload(); // Reload to reset form inputs
        }

        // Load saved wizard data on page load
        const currentStep = sessionStorage.getItem('wizard_currentStep');
        if (currentStep === '2') {
            const step1Data = JSON.parse(sessionStorage.getItem('wizard_step1') || '{}');
            if (step1Data.name) document.getElementById('name').value = step1Data.name;
            if (step1Data.email) document.getElementById('email').value = step1Data.email;
            nextStep(2);
        }

        // Load cart on page load
        updateCartDisplay();
        displaySessionData();
    </script>
</body>
</html>
```

**SessionStorage vs LocalStorage:**
- **SessionStorage**: cleared when tab/browser closes, scope = current tab only
- **LocalStorage**: persists forever until cleared, shared across same-origin tabs
- Same API for both: `setItem`, `getItem`, `removeItem`, `clear`, `length`, `key()`
- Same storage limit (~5-10MB)
- Use sessionStorage for sensitive temporary data, multi-step forms, tab-specific state

