<!DOCTYPE html>
<html>
<head>
    <title>Geolocation API Demo</title>
    <style>
        body { font-family: Arial; max-width: 800px; margin: 30px auto; padding: 20px; }
        button { padding: 10px 20px; margin: 5px; cursor: pointer; }
        .location-info { background: #f0f0f0; padding: 15px; border-radius: 8px; margin: 20px 0; }
        .error { background: #ffe0e0; border-left: 4px solid red; padding: 10px; margin: 10px 0; }
        .success { background: #e0ffe0; border-left: 4px solid green; }
        #map { height: 400px; margin-top: 20px; border-radius: 8px; }
    </style>
</head>
<body>
    <h1>Geolocation API Demo</h1>

    <button onclick="getLocation()">Get My Location</button>
    <button onclick="watchLocation()">Start Watching</button>
    <button onclick="stopWatching()">Stop Watching</button>

    <div id="output" class="location-info"></div>
    <div id="map"></div>

    <script>
        let watchId = null;

        function getLocation() {
            if (!navigator.geolocation) {
                showError('Geolocation is not supported by this browser.');
                return;
            }

            // Options for getCurrentPosition
            const options = {
                enableHighAccuracy: true,  // Use GPS if available
                timeout: 10000,            // Maximum time (ms) to wait
                maximumAge: 0              // Don't use cached position
            };

            navigator.geolocation.getCurrentPosition(showPosition, showError, options);
        }

        function showPosition(position) {
            const lat = position.coords.latitude;
            const lon = position.coords.longitude;
            const accuracy = position.coords.accuracy;
            const altitude = position.coords.altitude;
            const speed = position.coords.speed;
            const timestamp = new Date(position.timestamp).toLocaleString();

            const output = document.getElementById('output');
            output.className = 'location-info success';
            output.innerHTML = `
                <strong>✓ Location obtained successfully</strong><br>
                <strong>Latitude:</strong> ${lat}<br>
                <strong>Longitude:</strong> ${lon}<br>
                <strong>Accuracy:</strong> ±${Math.round(accuracy)} meters<br>
                ${altitude ? `<strong>Altitude:</strong> ${altitude} meters<br>` : ''}
                ${speed ? `<strong>Speed:</strong> ${speed} m/s<br>` : ''}
                <strong>Timestamp:</strong> ${timestamp}
            `;

            // Show on Google Maps
            showMap(lat, lon);

            // Optional: Send to server
            // fetch('/api/location', { method: 'POST', body: JSON.stringify({ lat, lon }) });
        }

        function showError(error) {
            const output = document.getElementById('output');
            output.className = 'location-info error';

            let message = '';
            switch(error.code) {
                case error.PERMISSION_DENIED:
                    message = 'User denied the request for geolocation.';
                    break;
                case error.POSITION_UNAVAILABLE:
                    message = 'Location information is unavailable.';
                    break;
                case error.TIMEOUT:
                    message = 'The request to get user location timed out.';
                    break;
                default:
                    message = 'An unknown error occurred.';
            }
            output.innerHTML = `<strong>❌ Error:</strong> ${message}`;
        }

        function showMap(lat, lon) {
            const mapDiv = document.getElementById('map');
            // Using OpenStreetMap (free, no API key needed)
            mapDiv.innerHTML = `
                <iframe 
                    width="100%" 
                    height="100%" 
                    frameborder="0" 
                    style="border:0"
                    src="https://www.openstreetmap.org/export/embed.html?bbox=${lon-0.01},${lat-0.01},${lon+0.01},${lat+0.01}&layer=mapnik&marker=${lat},${lon}"
                    allowfullscreen>
                </iframe>
            `;
        }

        // Watch position (continuous updates)
        function watchLocation() {
            if (!navigator.geolocation) {
                showError('Geolocation not supported');
                return;
            }

            const options = {
                enableHighAccuracy: true,
                timeout: 5000,
                maximumAge: 0
            };

            watchId = navigator.geolocation.watchPosition(
                (position) => {
                    const lat = position.coords.latitude;
                    const lon = position.coords.longitude;
                    document.getElementById('output').innerHTML += `<br>📍 Updated: ${lat}, ${lon} at ${new Date().toLocaleTimeString()}`;
                    showMap(lat, lon);
                },
                showError,
                options
            );

            document.getElementById('output').innerHTML = '<strong>📍 Watching location...</strong><br>';
        }

        function stopWatching() {
            if (watchId) {
                navigator.geolocation.clearWatch(watchId);
                watchId = null;
                document.getElementById('output').innerHTML += '<br><strong>⏹️ Stopped watching location.</strong>';
            }
        }

        // Check if geolocation is available on page load
        if (navigator.geolocation) {
            document.getElementById('output').innerHTML = '✓ Geolocation is supported. Click "Get My Location" to continue.';
        } else {
            document.getElementById('output').innerHTML = '❌ Geolocation is not supported by your browser.';
        }
    </script>
</body>
</html>
```

**Geolocation API Methods:**
- `getCurrentPosition(success, error, options)` - one-time location
- `watchPosition(success, error, options)` - continuous updates
- `clearWatch(watchId)` - stop watching

**Position object properties:**
- `coords.latitude`, `coords.longitude`
- `coords.accuracy` (meters)
- `coords.altitude`, `altitudeAccuracy`
- `coords.heading`, `speed`
- `timestamp`

**Error codes:**
- `PERMISSION_DENIED` (1)
- `POSITION_UNAVAILABLE` (2)
- `TIMEOUT` (3)

