    <h1>HTML5 Drag and Drop API</h1>

    <h2>Example 1: Simple Drag and Drop</h2>
    <div class="draggable" draggable="true" ondragstart="dragStart(event)" id="drag1">
        Drag Me!
    </div>

    <div class="dropzone" ondragover="dragOver(event)" ondrop="drop(event)">
        Drop Zone
    </div>

    <h2>Example 2: Task Manager (Drag between columns)</h2>
    <div style="display: flex;">
        <div class="dropzone" id="todo" ondragover="dragOver(event)" ondrop="dropTask(event)">
