            </div>
            <div draggable="true" class="task" ondragstart="dragTaskStart(event)" data-task="Build Project">
                Build Project
            </div>
        </div>

        <div class="dropzone" id="inprogress" ondragover="dragOver(event)" ondrop="dropTask(event)">
            <h3>In Progress</h3>
        </div>

        <div class="dropzone" id="done" ondragover="dragOver(event)" ondrop="dropTask(event)">
            <h3>Done</h3>
        </div>
