    <div class="draggable" draggable="true" ondragstart="dragDataStart(event)" data-color="red" style="background-color: red;">
        Red
    </div>
    <div class="draggable" draggable="true" ondragstart="dragDataStart(event)" data-color="blue" style="background-color: blue;">
