    </div>
    <div class="dropzone" ondragover="dragOver(event)" ondrop="dropColor(event)">
        Drop color here
    </div>

    <script>
        // Example 1: Simple drag and drop
        function dragStart(event) {
            event.dataTransfer.setData("text/plain", event.target.id);
            event.dataTransfer.effectAllowed = "copy";
        }

        function dragOver(event) {
            event.preventDefault(); // Required for drop
            event.dataTransfer.dropEffect = "copy";
            event.target.classList.add('drag-over');
        }

        function drop(event) {
            event.preventDefault();
            event.target.classList.remove('drag-over');
            const data = event.dataTransfer.getData("text/plain");
            const draggedElement = document.getElementById(data);
            event.target.appendChild(draggedElement);
        }

        // Example 2: Task manager
        function dragTaskStart(event) {
            event.dataTransfer.setData("text/plain", event.target.innerHTML);
            event.dataTransfer.setData("text/html", event.target.outerHTML);
            event.target.style.opacity = "0.5";
        }

        function dropTask(event) {
            event.preventDefault();
            const taskText = event.dataTransfer.getData("text/plain");
            const newTask = document.createElement("div");
            newTask.className = "task";
            newTask.setAttribute("draggable", "true");
            newTask.setAttribute("ondragstart", "dragTaskStart(event)");
            newTask.innerHTML = taskText;
            event.target.appendChild(newTask);

            // Remove original
            const original = document.querySelector(`[data-task="${taskText}"]`);
            if (original && original.parentElement !== event.target) {
                original.remove();
            }
            event.dataTransfer.clearData();
        }

        // Example 3: Drag custom data
        function dragDataStart(event) {
            const color = event.target.getAttribute('data-color');
            event.dataTransfer.setData("text/plain", color);
            event.dataTransfer.effectAllowed = "copy";
        }

        function dropColor(event) {
            event.preventDefault();
            const color = event.dataTransfer.getData("text/plain");
            event.target.style.backgroundColor = color;
            event.target.style.color = "white";
            event.target.innerHTML = `Dropped ${color} color`;
        }

        // Remove drag-over class
        document.querySelectorAll('.dropzone').forEach(zone => {
            zone.addEventListener('dragleave', (e) => {
                e.target.classList.remove('drag-over');
            });
        });
    </script>
