<!DOCTYPE html>
<html>
<head>
    <title>Web Storage vs Cookies</title>
    <style>
        body { font-family: Arial; max-width: 900px; margin: 30px auto; padding: 20px; }
        table { border-collapse: collapse; width: 100%; margin: 20px 0; }
        th, td { border: 1px solid #ddd; padding: 12px; text-align: left; vertical-align: top; }
        th { background-color: #4CAF50; color: white; }
        .demo { background: #f0f0f0; padding: 15px; margin: 15px 0; border-radius: 8px; }
        button { margin: 5px; padding: 8px 12px; cursor: pointer; }
    </style>
</head>
<body>
    <h1>Web Storage (localStorage/sessionStorage) vs Cookies</h1>

    <table>
        <thead>
            <tr><th>Feature</th><th>localStorage</th><th>sessionStorage</th><th>Cookies</th></tr>
        </thead>
        <tbody>
            <tr><td>Capacity</td><td>5-10MB</td><td>5-10MB</td><td>4KB</td></tr>
            <tr><td>Expiration</td><td>Permanent</td><td>Tab/Session</td><td>Manual/Date</td></tr>
            <tr><td>Sent to server</td><td>No</td><td>No</td><td>Yes (every request)</td></tr>
            <tr><td>Accessible by</td><td>JavaScript</td><td>JavaScript</td><td>JS & Server</td></tr>
            <tr><td>API complexity</td><td>Simple</td><td>Simple</td><td>Complex</td></tr>
        </tbody>
    </table>

    <h2>Demo: Compare Storage Methods</h2>

    <div class="demo">
        <h3>localStorage (persists across sessions)</h3>
        <input type="text" id="localKey" placeholder="Key" style="width: 150px;">
        <input type="text" id="localValue" placeholder="Value">
        <button onclick="saveLocal()">Save</button>
        <button onclick="getLocal()">Get</button>
        <button onclick="clearLocal()">Clear All</button>
        <p id="localOutput"></p>
    </div>

    <div class="demo">
        <h3>sessionStorage (clears when tab closes)</h3>
        <input type="text" id="sessionKey" placeholder="Key" style="width: 150px;">
        <input type="text" id="sessionValue" placeholder="Value">
        <button onclick="saveSession()">Save</button>
        <button onclick="getSession()">Get</button>
        <button onclick="clearSession()">Clear All</button>
        <p id="sessionOutput"></p>
        <small>⚠️ Refresh page: data persists. Close tab: data lost.</small>
    </div>

    <div class="demo">
        <h3>Cookies (4KB limit, sent to server)</h3>
        <input type="text" id="cookieKey" placeholder="Key" style="width: 150px;">
        <input type="text" id="cookieValue" placeholder="Value">
        <input type="number" id="cookieDays" placeholder="Days (0=session)" value="7" style="width: 100px;">
        <button onclick="saveCookie()">Save Cookie</button>
        <button onclick="getCookie()">Get Cookie</button>
        <button onclick="deleteCookie()">Delete Cookie</button>
        <p id="cookieOutput"></p>
        <small>🔒 Cookies are sent with every HTTP request automatically.</small>
    </div>

    <div class="demo">
        <h3>Store Complex Data (Objects/Arrays)</h3>
        <button onclick="saveObject()">Save User Object</button>
        <button onclick="loadObject()">Load User Object</button>
        <p id="objectOutput"></p>
    </div>

    <script>
        // localStorage operations
        function saveLocal() {
            const key = document.getElementById('localKey').value;
            const value = document.getElementById('localValue').value;
            if (key) {
                localStorage.setItem(key, value);
                document.getElementById('localOutput').innerHTML = `✅ Saved: ${key} = ${value}`;
            }
        }

        function getLocal() {
            const key = document.getElementById('localKey').value;
            if (key) {
                const value = localStorage.getItem(key);
                document.getElementById('localOutput').innerHTML = value ? `📖 ${key} = ${value}` : `❌ Key '${key}' not found`;
            }
        }

        function clearLocal() {
            localStorage.clear();
            document.getElementById('localOutput').innerHTML = '🗑️ All localStorage cleared';
        }

        // sessionStorage operations
        function saveSession() {
            const key = document.getElementById('sessionKey').value;
            const value = document.getElementById('sessionValue').value;
            if (key) {
                sessionStorage.setItem(key, value);
                document.getElementById('sessionOutput').innerHTML = `✅ Saved: ${key} = ${value}`;
            }
        }

        function getSession() {
            const key = document.getElementById('sessionKey').value;
            if (key) {
                const value = sessionStorage.getItem(key);
                document.getElementById('sessionOutput').innerHTML = value ? `📖 ${key} = ${value}` : `❌ Key '${key}' not found`;
            }
        }

        function clearSession() {
            sessionStorage.clear();
            document.getElementById('sessionOutput').innerHTML = '🗑️ All sessionStorage cleared';
        }

        // Cookie operations (manual implementation)
        function saveCookie() {
            const key = document.getElementById('cookieKey').value;
            const value = document.getElementById('cookieValue').value;
            const days = parseInt(document.getElementById('cookieDays').value);

            if (key) {
                let expires = '';
                if (days > 0) {
                    const date = new Date();
                    date.setTime(date.getTime() + (days * 24 * 60 * 60 * 1000));
                    expires = `; expires=${date.toUTCString()}`;
                }
                document.cookie = `${key}=${encodeURIComponent(value)}${expires}; path=/`;
                document.getElementById('cookieOutput').innerHTML = `✅ Cookie saved: ${key}=${value}`;
            }
        }

        function getCookie() {
            const key = document.getElementById('cookieKey').value;
            if (key) {
                const cookies = document.cookie.split('; ');
                for (let cookie of cookies) {
                    const [ckey, cvalue] = cookie.split('=');
                    if (ckey === key) {
                        document.getElementById('cookieOutput').innerHTML = `📖 ${key} = ${decodeURIComponent(cvalue)}`;
                        return;
                    }
                }
                document.getElementById('cookieOutput').innerHTML = `❌ Cookie '${key}' not found`;
            }
        }

        function deleteCookie() {
            const key = document.getElementById('cookieKey').value;
            if (key) {
                document.cookie = `${key}=; expires=Thu, 01 Jan 1970 00:00:00 UTC; path=/`;
                document.getElementById('cookieOutput').innerHTML = `🗑️ Cookie '${key}' deleted`;
            }
        }

        // Store objects
        function saveObject() {
            const user = {
                name: 'John Doe',
                email: 'john@example.com',
                preferences: { theme: 'dark', notifications: true },
                lastLogin: new Date().toISOString()
            };
            localStorage.setItem('user', JSON.stringify(user));
            document.getElementById('objectOutput').innerHTML = '✅ User object saved to localStorage';
        }

        function loadObject() {
            const userJson = localStorage.getItem('user');
            if (userJson) {
                const user = JSON.parse(userJson);
                document.getElementById('objectOutput').innerHTML = `
                    📖 Loaded user:<br>
                    Name: ${user.name}<br>
                    Email: ${user.email}<br>
                    Theme: ${user.preferences.theme}<br>
                    Last login: ${user.lastLogin}
                `;
            } else {
                document.getElementById('objectOutput').innerHTML = '❌ No user object found';
            }
        }

        // Display existing data on load
        window.onload = () => {
            console.log('localStorage items:', localStorage.length);
            console.log('sessionStorage items:', sessionStorage.length);
            console.log('Cookies:', document.cookie);
        };
    </script>

    <h3>When to use what?</h3>
    <ul>
        <li><strong>localStorage:</strong> User preferences, themes, offline data, long-term storage</li>
        <li><strong>sessionStorage:</strong> Form wizard data, shopping cart (tab-specific), temporary state</li>
        <li><strong>Cookies:</strong> Authentication tokens, session IDs, server-required data (HttpOnly for security)</li>
    </ul>
</body>
</html>
```

**Key Differences:**
- **Capacity**: Web storage (5-10MB) >> Cookies (4KB)
- **Network**: Cookies sent with every HTTP request (slower), Web storage never sent
- **Expiration**: localStorage permanent, sessionStorage tab-only, cookies manual
- **Access**: Web storage JS-only, cookies accessible by JS and server
- **Security**: Cookies can be HttpOnly (inaccessible to JS, XSS protection)
